#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Fatih's request (16:30): one clean, host-split Autoware run on the latest mainline image with today's code, then the full
# task-extraction pipeline — the data for the presentation. Config = TASK 1 session (fish_20261025_134134) on fishwait28:
# lttng+nsys (MODES=nsys), tier max, container shim ON, state-link extra events, CDDS XML, app on P-cores 0,2,4,6,8,10 /
# observers on 12-17 (night_runs.sh defaults). Host: split before, off after (reported in the log).
# Usage: scripts/aw_clean_run_20261026.sh [log_dir]      env: MODES (default nsys), IMG (default fishwait28)
set -u; cd "$(dirname "$0")/.."
LD=${1:-$HOME/fish_traces/aw_clean_20261026}; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/clean_run.log"; }
IMG=${IMG:-autoware-dev-trt-a1000-fishwait29:latest}; MODES=${MODES:-nsys}
EV=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids
# 2026-10-26 evening: METHOD_SHIM=1 (default 1, image >= fishwait29) = user-listed method probes; ROUTE=1 (default 1) = the
# logging_simulator gets a route through the AD API once the ego moves (scripts/autoware_runs/inject_route.py, goal from
# config/sim_route_sample_rosbag.json) so that planning and control compute for real during the replay.
METHOD_SHIM=${METHOD_SHIM:-1}; ROUTE=${ROUTE:-1}; INJECT_AT=${INJECT_AT:-15}
EXTRA_PLAN="FISH_METHOD_SHIM=$METHOD_SHIM"
[ "$ROUTE" = 1 ] && EXTRA_PLAN="$EXTRA_PLAN FISH_INJECT_AT=$INJECT_AT FISH_INJECT_CMD='python3 /root/fish_interfere/scripts/autoware_runs/inject_route.py /root/fish_interfere/config/sim_route_sample_rosbag.json'"
docker image inspect "$IMG" >/dev/null 2>&1 || { log "image $IMG missing"; exit 2; }
[ -n "$(docker ps -q --filter name=ovh- --filter name=migf_ --filter name=mig_)" ] && { log "another experiment container is running; refusing to start"; exit 3; }
# 2026-10-26 16:45: the first attempt ran on battery (adapter out, CPU capped at 400 MHz) — refuse to start without AC, and log
# the power state every 20 s during the run so a run with an AC loss is flagged invalid.
AC=$(timeout 3 cat /sys/class/power_supply/AC/online 2>/dev/null); [ "$AC" = 1 ] || { log "AC adapter not online (AC/online=$AC); refusing to start"; exit 5; }
( while :; do echo "$(date +%T) AC=$(timeout 3 cat /sys/class/power_supply/AC/online 2>/dev/null) BAT=$(timeout 3 cat /sys/class/power_supply/BAT0/status 2>/dev/null) $(timeout 3 cat /sys/class/power_supply/BAT0/capacity 2>/dev/null)% MHz=$(grep -m1 MHz /proc/cpuinfo | awk '{print int($4)}')" >> "$LD/power.log"; sleep 20; done ) & PWPID=$!
trap 'kill $PWPID 2>/dev/null' EXIT
SPLIT=${SPLIT:-1}     # SPLIT=0: evidence run on an off host (no timing claim)
if [ "$SPLIT" = 1 ]; then sudo -n /usr/local/sbin/fish-host-perf-mode split >> "$LD/clean_run.log" 2>&1 || { log "split failed; abort"; exit 1; }; fi
log "host $( [ "$SPLIT" = 1 ] && echo SPLIT || echo OFF (no split) ); run: IMG=$IMG MODES=$MODES container shim=1 method shim=$METHOD_SHIM route=$ROUTE (inject at replay +$INJECT_AT s) extra=$EV"
echo "awclean IMG=$IMG MODES=$MODES FISH_CONTAINER_SHIM=1 FISH_EXTRA_EVENTS=$EV $EXTRA_PLAN" > "$LD/plan.txt"
FISH_ALLOW_FORK=1 NIGHT_RUNS_NO_SPLIT=1 bash scripts/night_runs.sh "$LD" < "$LD/plan.txt" >> "$LD/night_runs.out" 2>&1
[ "$SPLIT" = 1 ] && sudo -n /usr/local/sbin/fish-host-perf-mode off >> "$LD/clean_run.log" 2>&1; log "host OFF"
kill $PWPID 2>/dev/null; NAC=$(grep -c "AC=0\|AC= " "$LD/power.log"); log "power during the run: $(wc -l < "$LD/power.log") samples, AC lost in $NAC -> $( [ "$NAC" = 0 ] && echo 'RUN POWER OK' || echo 'RUN INVALID (AC lost)')"
L=$(grep "^awclean " "$LD/night_runs.txt" | tail -1); log "night_runs: $L"
C=$(echo "$L" | awk '{print $2}'); RUN=$(ls -d "$C"/${MODES}_1 2>/dev/null | head -1)
[ -n "$RUN" ] && [ -f "$RUN/session.txt" ] || { log "no run dir / session.txt under $C"; exit 4; }
S=$(basename "$(cat "$RUN/session.txt")"); log "session $S -> pipeline"
[ "$ROUTE" = 1 ] && { log "route injector: $(grep -E 'set_route_points|routing state|trajectory:' "$HOME/fish_traces/$S/fishlog/inject.log" 2>/dev/null | tail -3 | cut -c1-160 | tr '\n' ' ')"; }
A=$HOME/fish_traces/analysis_$S
bash scripts/post_run_pipeline.sh "$RUN" "$A" > "$LD/pipeline.log" 2>&1 || log "pipeline rc=$?"
grep -E "FAILED|PIPELINE DONE|health:" "$LD/pipeline.log" | head -6 | sed 's/^/  /' | tee -a "$LD/clean_run.log"
grep -E "^vertices:|^FISH tasks:|intra-process identity|dds pairs by|join edges:|publishes \(data topics\)" "$A/fish_tasks.txt" 2>/dev/null | cut -c1-300 | sed 's/^/  /' | tee -a "$LD/clean_run.log"
python3 - "$A/fish_tasks.json" <<'PY' | tee -a "$LD/clean_run.log"
import json, sys, collections
d = json.load(open(sys.argv[1])); c = collections.Counter()
for t in d.get('tasks', []):
    for e in t.get('edges', []): c[f"{e.get('kind')}:{e.get('prov')}"] += 1
print("  task edge evidence:", dict(c.most_common())); print("  inactive:", len(d.get('inactive_edges', [])), "candidates:", len(d.get('candidates', [])), "unpaired:", len(d.get('unpaired', [])))
PY
log "CLEAN RUN DONE: session $S, analysis $A"
